/* ------------------------- 홈택스 부서 계정(담당자) -------------------
 * 총괄업체 관리의 각 업체는 담당자 성명이 아니라 이 부서 계정 ID(deptId)를 참조한다.
 * 담당자가 퇴사·인수인계되면 여기서 해당 ID의 "담당자명"만 바꿔주면
 * 그 ID를 물고 있는 모든 거래처가 자동으로 새 담당자로 인수인계된다.
 * ------------------------------------------------------------------ */
function deptAccount(id, o) {
  return {
    id,
    name: o.name || "",
    phone: o.phone || "",
    email: o.email || "",
    pwEntered: !!o.pwEntered,   // 홈택스 비밀번호 입력 여부
    otpEntered: !!o.otpEntered, // 2차 인증 번호 입력 여부
  };
}
