function JojReportModal({ 대표, 대표Label, kind, yearLabel, dueLabel, dueDate, sites, firm, onClose }) {
  const F = firm || {};
  const isCorp = kind === "법인";
  const kindTitle = isCorp ? "법인결산 및 세무조정" : "종합소득세 결산 및 세무조정";
  const feeTable = isCorp ? CORP_FEE_TABLE : INDIV_FEE_TABLE;
  const feeNote = isCorp ? CORP_FEE_NOTE : INDIV_FEE_NOTE;
  const acctLine = [F.bank, F.account].filter(Boolean).join(" ") || "________________";

  const calcs = sites.map((s) => jojCalc(s.income, s.joj.가산율, s.joj.부대, s.joj.청구, kind));
  const grand = calcs.reduce((a, c) => a + c.bill, 0);

  const td = { border: "1px solid #333", padding: "7px 10px" };
  const L = ({ label, value, note, bold }) => (
    <tr>
      <td style={{ ...td, fontWeight: bold ? 800 : 500, background: bold ? "#F2F5F9" : "#fff" }}>{label}</td>
      <td style={{ ...td, textAlign: "right", fontVariantNumeric: "tabular-nums", fontWeight: bold ? 800 : 500 }}>{won(value)} 원</td>
      <td style={{ ...td, fontSize: 11, color: "#555" }}>{note || ""}</td>
    </tr>
  );

  return (
    <div style={{ ...S.overlay, zIndex: 80 }} onClick={onClose}>
      <div className="invoiceDoc" style={{ ...S.invoice, width: 680 }} onClick={(e) => e.stopPropagation()}>

        {/* 1페이지 : 사업장별 조정료 합계 요약 */}
        <div style={{ pageBreakAfter: sites.length > 0 ? "always" : "auto" }}>
          <div style={{ fontSize: 20, fontWeight: 800, textAlign: "center", margin: "0 0 20px", letterSpacing: -0.3 }}>{yearLabel} {kindTitle} 보수 안내</div>
          <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 18 }}>
            <div style={{ textAlign: "left" }}>
              <div style={{ fontSize: 15, fontWeight: 800 }}>{대표}</div>
              <div style={{ fontSize: 12.5, color: "#333", marginTop: 4 }}>{대표Label || "대표자"} 귀하</div>
            </div>
          </div>
          <p style={{ fontSize: 13, lineHeight: 1.9, margin: "0 0 18px" }}>
            1. 귀하의 무궁한 발전을 기원드립니다.<br />
            2. {yearLabel.replace(/ 귀속$/, "년 귀속")} {kindTitle}에 따라 신고를 완료하였으며, 보유하신 사업장별 세무조정보수를 아래와 같이 안내드리오니 <b>{dueDate}</b>까지 입금을 부탁드립니다. 사업장별 세부 산출근거는 다음 장부터 안내드립니다.
          </p>
          <div style={{ fontSize: 13, fontWeight: 800, margin: "0 0 8px" }}>가. 사업장별 조정료 합계</div>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5, marginBottom: 10 }}>
            <thead>
              <tr>
                <td style={{ ...td, fontWeight: 700, background: "#F2F5F9", textAlign: "center" }}>사업장</td>
                <td style={{ ...td, fontWeight: 700, background: "#F2F5F9", textAlign: "center" }}>수입금액</td>
                <td style={{ ...td, fontWeight: 700, background: "#F2F5F9", textAlign: "center" }}>조정료 (부가세 포함)</td>
              </tr>
            </thead>
            <tbody>
              {sites.map((s, i) => (
                <tr key={i}>
                  <td style={{ ...td, textAlign: "center" }}>사업장{i + 1}{s.name ? ` · ${s.name}` : ""}</td>
                  <td style={{ ...td, textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{won(s.income)} 원</td>
                  <td style={{ ...td, textAlign: "right", fontWeight: 700, fontVariantNumeric: "tabular-nums" }}>{won(calcs[i].bill)} 원</td>
                </tr>
              ))}
              <tr>
                <td style={{ ...td, fontWeight: 800, background: "#F2F5F9", textAlign: "center" }} colSpan={2}>합계</td>
                <td style={{ ...td, fontWeight: 800, background: "#F2F5F9", textAlign: "right", fontVariantNumeric: "tabular-nums" }}>{won(grand)} 원</td>
              </tr>
            </tbody>
          </table>
          <div style={{ fontSize: 12, color: "#333" }}>나. 계좌 : {acctLine}{F.name ? `(${F.name})` : ""}</div>
        </div>

        {/* 2페이지 이후 : 사업장별 산출근거 (사업장마다 별도 페이지) */}
        {sites.map((s, i) => (
          <div key={i} style={{ pageBreakAfter: i < sites.length - 1 ? "always" : "auto" }}>
            <div style={{ fontSize: 17, fontWeight: 800, margin: "0 0 4px", color: NAVY }}>사업장{i + 1}{s.name ? ` · ${s.name}` : ""} 산출근거</div>
            <div style={{ fontSize: 11.5, color: SUB, marginBottom: 16 }}>{yearLabel} · {대표Label || "대표자"} {대표}</div>

            <div style={{ fontSize: 13, fontWeight: 800, margin: "0 0 8px" }}>가. 산출근거</div>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11.5, marginBottom: 6 }}>
              <thead>
                <tr>
                  <td style={{ ...td, fontWeight: 700, background: "#F2F5F9", textAlign: "center" }}>수입{isCorp ? "(자산)" : ""}금액</td>
                  <td style={{ ...td, fontWeight: 700, background: "#F2F5F9", textAlign: "center" }}>기준보수액{isCorp ? "" : "(세무조정만 수행할 경우)"}</td>
                </tr>
              </thead>
              <tbody>
                {feeTable.map((row, ri) => (
                  <tr key={ri}>
                    <td style={{ ...td, padding: "5px 10px" }}>{row.range}</td>
                    <td style={{ ...td, padding: "5px 10px" }}>{row.formula}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div style={{ fontSize: 10.5, color: "#555", whiteSpace: "pre-line", lineHeight: 1.6, marginBottom: 18 }}>{feeNote}</div>

            <div style={{ fontSize: 13, fontWeight: 800, margin: "0 0 8px" }}>나. 세무조정보수 산정내용</div>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5, marginBottom: 10 }}>
              <tbody>
                <tr>
                  <td style={{ ...td, fontWeight: 700, background: "#F2F5F9", width: 140, textAlign: "center" }}>사업장</td>
                  <td style={{ ...td, textAlign: "center" }}>사업장{i + 1}{s.name ? ` · ${s.name}` : ""}</td>
                  <td style={{ ...td, fontWeight: 700, background: "#F2F5F9", width: 140, textAlign: "center" }}>수입{isCorp ? "(자산)" : ""}금액</td>
                  <td style={{ ...td, textAlign: "center", fontVariantNumeric: "tabular-nums" }}>{won(s.income)} 원</td>
                </tr>
              </tbody>
            </table>
            <div style={{ fontSize: 12, fontWeight: 700, margin: "0 0 6px" }}>&lt;{kind}조정료 산정내역&gt;</div>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
              <tbody>
                <L label="위 보수표에 의한 보수기준금액" value={calcs[i].base} />
                <L label="가산금액" value={calcs[i].add} note={(s.joj.가산율 || 0) > 0 ? (s.joj.가산사유 || `${Math.round(s.joj.가산율 * 100)}% 가산`) : ""} />
                <L label="기타 부대비용 가산액" value={s.joj.부대 || 0} note="제본·택배 등" />
                <L label="개별조정액" value={calcs[i].indiv} note="천원미만 절사" bold />
                <L label={`${kind}조정료 보수총액`} value={calcs[i].total} bold />
                <L label="부가가치세 (10%)" value={calcs[i].vat} note={calcs[i].discount < 0 ? `${won(-calcs[i].discount)}원 할인` : ""} />
                <L label="청구액 (부가세 포함)" value={calcs[i].bill} bold />
              </tbody>
            </table>
            {s.joj.청구 != null && Math.round(s.joj.청구) !== Math.round(calcs[i].normal) && (
              <div style={{ fontSize: 11.5, color: calcs[i].discount < 0 ? "#B4232A" : "#333", margin: "8px 0 0", border: "1px solid #333", borderRadius: 4, padding: "7px 10px" }}>
                <b>청구액 수정 사유</b> : {s.joj.청구사유 || "—"}
              </div>
            )}
          </div>
        ))}

        {F.invoiceLogo && (
          <div style={{ display: "flex", justifyContent: "center", marginTop: 24 }}>
            <img src={F.invoiceLogo} alt="" style={{ maxWidth: 340, maxHeight: 130, objectFit: "contain" }} />
          </div>
        )}

        <div className="noprint" style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 22 }}>
          <button className="btnGhost2" style={S.btnCancel} onClick={onClose}>닫기</button>
          <button className="btnGold" style={S.btnConfirm} onClick={() => window.print()}>인쇄</button>
        </div>
      </div>
    </div>
  );
}
function InfoChip({ label, value, gold }) {
  return (
    <div style={{ flex: 1, background: gold ? GOLD_SOFT : "#F4F7FB", border: `1px solid ${gold ? "#E7D399" : LINE}`, borderRadius: 8, padding: "8px 10px" }}>
      <div style={{ fontSize: 10.5, color: SUB }}>{label}</div>
      <div style={{ fontSize: 13.5, fontWeight: 800, color: gold ? "#8A6608" : NAVY }}>{value}</div>
    </div>
  );
}

/* ============================== 법인세 =============================
 * 업로드된 "법인세무조정 명단" 형식: 성실여부·법인명·대표자·업종
 *  · {작년} 사업연도(수입/순이익/소득률/조정료, 자동)
 *  · {올해} 사업연도(수입[부가세 확정 자동·수정가능]/순이익[입력]/소득률/조정료청구액[팝업]/할인율/조정료)
 *  · 신고여부 · 비고
 * 조정료 팝업 = 법인조정 보수표. 입금일: 일반 3/31, 성실 4/30.
 * ------------------------------------------------------------------ */
function seedCorp() {
  const j = (rate) => ({ 가산율: rate, 부대: 0, 수입: null, 청구: null });
  const mk = (id, 성실, 수입, 순이익, rate, 완료, 비고) =>
    ({ id, 성실, 수입, 순이익, 완료: 완료 || "자료 수집 필요", 비고: 비고 || "", 조정료: j(rate) });
  return {
    2023: [
      mk("c2", "일반", 5369805212, -1955934968, 0.3),
      mk("c4", "일반", 1180000000, 62000000, 0.2),
      mk("c5", "성실", 2610000000, -95000000, 0.2),
    ],
    2024: [
      mk("c2", "일반", 9413629881, -464602018, 0.3, "신고서 작성 완료"),
      mk("c4", "일반", 1240000000, 95198011, 0.2, "자료 수집 필요"),
      mk("c5", "성실", 2960000000, 14049884, 0.2, "자료 수집 필요", "자산/부채규모 190억원"),
    ],
  };
}
function CorporateTab({ profiles, onOpenProfile, store, setStore, vatStore, firm, viewAsDept, staffNameOf }) {
  const [year, setYear] = useState(2024);
  const [q, setQ] = useState("");
  const isMaster = !viewAsDept;
  const [pop, setPop] = useState(null); // id
  const [toast, setToast] = useState("");
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(""), 2400); return () => clearTimeout(t); }, [toast]);
  const rows = (store[year] || [])
    .filter((r) => (profiles[r.id] ? profiles[r.id].name : r.id).includes(q.trim()))
    .filter((r) => isMaster || (profiles[r.id] && profiles[r.id].deptId === viewAsDept));
  const prev = store[year - 1] || [];
  const setRow = (id, patch) => setStore((s) => ({ ...s, [year]: s[year].map((r) => (r.id === id ? { ...r, ...patch } : r)) }));
  const setJoj = (id, patch) => setStore((s) => ({ ...s, [year]: s[year].map((r) => (r.id === id ? { ...r, 조정료: { ...r.조정료, ...patch } } : r)) }));
  // 총괄업체 관리에 등록된 법인 중 해당 사업연도에 아직 없는 법인을 불러온다.
  const loadFromMaster = () => {
    const existing = new Set((store[year] || []).map((r) => r.id));
    const additions = Object.values(profiles).filter((p) => p.gubun === "법인" && !existing.has(p.id))
      .map((p) => ({ id: p.id, 성실: "일반", 수입: 0, 순이익: 0, 완료: "자료 수집 필요", 비고: "", 조정료: { 가산율: 0, 부대: 0, 수입: null, 청구: null } }));
    if (!additions.length) { setToast("불러올 신규 법인이 없습니다."); return; }
    setStore((s) => ({ ...s, [year]: [...(s[year] || []), ...additions] }));
    setToast(`총괄업체 관리에서 법인 ${additions.length}곳을 불러왔습니다.`);
  };
  const importTaxbot = () => {
    if (!firm?.taxbotId) { setToast("사무소 설정에서 택스봇 ID·PW를 먼저 등록해주세요."); return; }
    setToast("택스봇에서 최신 법인세 데이터를 불러왔습니다.");
  };

  const nameOf = (id) => (profiles[id] ? profiles[id].name : id);
  const calcOf = (r) => (r ? jojCalc(r.조정료.수입 != null ? r.조정료.수입 : (r.수입 || 0), r.조정료.가산율, r.조정료.부대, r.조정료.청구, "법인") : null);
  const rate = (ni, rev) => (rev ? ni / rev : null);
  const pct = (x) => (x == null ? "—" : `${(x * 100).toFixed(1)}%`);
  const prevOf = (id) => prev.find((r) => r.id === id);
  const doneCnt = rows.filter((r) => /전달 완료$/.test(r.완료)).length;

  const W = [64, 148, 84, 126, 116, 116, 64, 106, 116, 116, 64, 118, 64, 106, 138, 128];

  return (
    <div>
      <div style={S.toolbar}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <Select value={year} onChange={(v) => setYear(+v)} options={yearRange(year).map((y) => ({ v: y, l: `${y} 사업연도` }))} width={128} />
          <div>
            <div style={{ fontSize: 16, fontWeight: 800, color: NAVY }}>법인세 신고 관리</div>
            <div style={{ fontSize: 11.5, color: SUB, marginTop: 2 }}>총괄업체 관리의 법인을 집계합니다. 수입금액은 부가세 확정 공급가액에서 자동으로 불러옵니다(수정가능). 소득률·할인율·조정료는 자동 계산됩니다.</div>
          </div>
          <button className="btnGold" style={S.updateBtn} onClick={loadFromMaster}><RefreshCw size={14} /> 총괄업체 데이터 불러오기</button>
          <button className="btnTaxbot" style={S.taxbotBtn} onClick={importTaxbot}><Link2 size={13} /> 택스봇 연동</button>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
          {!isMaster && (
            <div style={{ fontSize: 12, color: NAVY, fontWeight: 700, background: NAVY_SOFT, border: `1px solid ${LINE}`, borderRadius: 8, padding: "6px 10px" }}>
              {staffNameOf(viewAsDept)} 담당 거래처만 표시 중
            </div>
          )}
          <div style={S.searchBox}><Search size={14} color={SUB} /><input className="fx2" style={S.search} placeholder="법인명 검색" value={q} onChange={(e) => setQ(e.target.value)} /></div>
          <Metric label="법인 수" value={`${rows.length}곳`} />
          <Metric label="신고 완료" value={`${doneCnt}곳`} accent="#1E7A45" />
          <Metric label="신고 필요" value={`${rows.length - doneCnt}곳`} accent="#B4232A" />
        </div>
      </div>

      <div style={S.gridWrap}><div style={S.gridScroll}>
        <table style={{ ...S.table, minWidth: W.reduce((a, b) => a + b, 0) }}>
          <colgroup>{W.map((w, i) => <col key={i} style={{ width: w }} />)}</colgroup>
          <thead>
            <tr>
              <th style={{ ...S.th, ...S.thSub, top: 0 }} rowSpan={2}>{"성실\n여부"}</th>
              <th style={{ ...S.th, ...S.thSub, top: 0 }} rowSpan={2}>법인명</th>
              <th style={{ ...S.th, ...S.thSub, top: 0 }} rowSpan={2}>대표자명</th>
              <th style={{ ...S.th, ...S.thSub, top: 0 }} rowSpan={2}>업종</th>
              <th style={{ ...S.th, ...S.thGroup }} colSpan={4}>{year - 1} 사업연도 (작년)</th>
              <th style={{ ...S.th, ...S.thGroup, background: GOLD_SOFT, color: "#8A6608" }} colSpan={6}>{year} 사업연도 (올해)</th>
              <th style={{ ...S.th, ...S.thSub, top: 0 }} rowSpan={2}>신고여부</th>
              <th style={{ ...S.th, ...S.thSub, top: 0 }} rowSpan={2}>비고</th>
            </tr>
            <tr>
              {["수입금액", "순이익", "소득률", "조정료"].map((h, i) => <th key={"a" + i} style={{ ...S.th, ...S.thSub2 }}>{h}</th>)}
              {["수입금액", "순이익", "소득률", "조정료\n청구액", "할인율", "조정료"].map((h, i) => <th key={"b" + i} style={{ ...S.th, ...S.thSub2, background: GOLD_SOFT }}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => {
              const p = profiles[r.id] || {};
              const c = calcOf(r);
              const pr = prevOf(r.id); const pc = calcOf(pr);
              const disc = c && c.normal ? Math.max(0, (c.normal - c.bill) / c.normal) : 0;
              return (
                <tr key={r.id} className="row">
                  <td style={{ ...S.td, padding: 4 }}><MiniSelect value={r.성실} options={["일반", "성실"]} onChange={(v) => setRow(r.id, { 성실: v })} /></td>
                  <td style={{ ...S.td, textAlign: "left", paddingLeft: 12 }}><button className="nameLink" style={S.nameLink} onClick={() => onOpenProfile(r.id)}>{nameOf(r.id)}</button></td>
                  <td style={{ ...S.td, ...S.tbAuto, fontSize: 12 }}>{p.ceoName || "—"}</td>
                  <td style={{ ...S.td, ...S.tbAuto, textAlign: "left", paddingLeft: 10, fontSize: 11.5 }}>{p.industry || "—"}</td>
                  {/* 작년 (자동·읽기전용) */}
                  <td style={{ ...S.td, ...S.tbAuto, textAlign: "right", paddingRight: 8, fontVariantNumeric: "tabular-nums" }}>{pr ? won(pr.수입) : "—"}</td>
                  <td style={{ ...S.td, ...S.tbAuto, textAlign: "right", paddingRight: 8, fontVariantNumeric: "tabular-nums", color: pr && pr.순이익 < 0 ? "#B4232A" : INK }}>{pr ? won(pr.순이익) : "—"}</td>
                  <td style={{ ...S.td, ...S.tbAuto, fontSize: 11 }}>{pr ? pct(rate(pr.순이익, pr.수입)) : "—"}</td>
                  <td style={{ ...S.td, ...S.tbAuto, textAlign: "right", paddingRight: 8, fontVariantNumeric: "tabular-nums" }}>{pc ? won(pc.bill) : "—"}</td>
                  {/* 올해 */}
                  <td style={{ ...S.td, padding: 4 }}><VatNum value={r.수입} onChange={(v) => setRow(r.id, { 수입: v || 0 })} /></td>
                  <td style={{ ...S.td, padding: 4 }}><VatNum value={r.순이익} onChange={(v) => setRow(r.id, { 순이익: v == null ? 0 : v })} /></td>
                  <td style={{ ...S.td, fontSize: 11, color: (r.순이익 || 0) < 0 ? "#B4232A" : INK }}>{pct(rate(r.순이익, r.수입))}</td>
                  <td style={{ ...S.td, textAlign: "right", paddingRight: 8 }}><button className="arlink" style={{ ...S.arlink, color: NAVY }} onClick={() => setPop(r.id)}>{won(c.normal)}</button></td>
                  <td style={{ ...S.td, fontSize: 11, color: disc > 0 ? "#B4232A" : SUB }}>{pct(disc)}</td>
                  <td style={{ ...S.td, textAlign: "right", paddingRight: 8, fontWeight: 700, fontVariantNumeric: "tabular-nums" }}>{won(c.bill)}</td>
                  <td style={{ ...S.td, padding: 4 }}><MiniSelect value={r.완료} options={JONG_DONE3} onChange={(v) => setRow(r.id, { 완료: v })} wide /></td>
                  <td style={{ ...S.td, padding: 4 }}><input className="fx" style={S.noteInput} value={r.비고 || ""} placeholder="비고" onChange={(e) => setRow(r.id, { 비고: e.target.value })} /></td>
                </tr>
              );
            })}
            {rows.length === 0 && <tr><td colSpan={16} style={S.noRow}>법인이 없습니다.</td></tr>}
          </tbody>
        </table>
      </div></div>

      {pop && store[year] && (() => {
        const r = store[year].find((x) => x.id === pop);
        if (!r) return null;
        const p = profiles[r.id] || {};
        return <JojeongModal
          상호={nameOf(r.id)} 대표={p.ceoName || "—"} 대표Label="대표이사" kind="법인"
          yearLabel={`${year} 귀속`} dueLabel={r.성실 === "성실" ? "입금일 (성실)" : "입금일"}
          dueDate={corpDueDate(year, p.closingMonth, r.성실 === "성실" ? 4 : 3)}
          joj={r.조정료} defaultIncome={r.수입}
          addHints={[{ pct: 0.2, label: "기장·조정/지점" }, { pct: 0.3, label: "건설·시행사" }, { pct: 0.1, label: "외부감사" }]}
          onChange={(patch) => setJoj(r.id, patch)} onClose={() => setPop(null)} firm={firm} />;
      })()}
      {toast && <div style={S.toast}>{toast}</div>}
    </div>
  );
}

/* ------------------------------- utils ----------------------------- */
function range(a, b) { const r = []; for (let i = a; i <= b; i++) r.push(i); return r; }
/* 탭 공통 연도 선택 범위: 선택된(또는 현재) 연도를 기준으로 과거 5년 ~ 미래 2년.
   연도를 선택할 때마다 그 선택 연도를 기준으로 창이 다시 계산되어, 계속 앞으로도 뒤로도 이동 가능합니다. */
function yearRange(anchorYear, pastYears = 5, futureYears = 2) {
  const base = anchorYear != null ? anchorYear : new Date().getFullYear();
  return range(base - pastYears, base + futureYears);
}

