function Style() {
  return (
    <style>{`
      * { box-sizing: border-box; }
      body { margin: 0; }
      .fx:focus, .fx2:focus { border-color:${NAVY}; }
      .btnPrimary:hover { background:${NAVY_DK}; }
      .btnGold:hover { filter:brightness(.97); }
      .btnGhost:hover, .btnGhost2:hover { background:rgba(0,0,0,.03); }
      .btnTaxbot:hover { background:#E1E9F4; }
      .staffItem:hover { background:#F2F5F9; }
      .tab:hover { color:#DCE5F0; }
      .row:hover td { background:#F5F8FC; }
      .row:hover td[style*="sticky"] { background:#F5F8FC; }
      .chk:hover { border-color:${GOLD}; }
      .chip:hover { filter:brightness(.97); }
      .segb:hover { background:#EEF2F7; }
      .arlink:hover { filter:brightness(.9); }
      .mlink:hover { background:#E1E9F4; }
      .pickRow:hover { background:#F5F8FC; }
      .sel:focus, .pay:focus, .fx:focus, .fx2:focus { outline:2px solid ${NAVY}22; }
      @media print {
        body * { visibility: hidden; }
        .invoiceDoc, .invoiceDoc * { visibility: visible; }
        .invoiceDoc { position: fixed; left: 0; top: 0; box-shadow: none; border-radius: 0; }
        .noprint { display: none !important; }
      }
      ::-webkit-scrollbar { width:11px; height:11px; }
      ::-webkit-scrollbar-thumb { background:#C6D0DC; border-radius:6px; border:3px solid #fff; }
      ::-webkit-scrollbar-thumb:hover { background:#A9B6C6; }
    `}</style>
  );
}

